const leaseFree = (row, nowMs) => Number(row.presa_fino_ms) <= nowMs;
const execOf = (execId) => {
  if ((typeof execId !== 'string' && typeof execId !== 'number') || String(execId).trim() === '' || String(execId) === 'undefined') {
