const PAGE_SIZE = 100;
const MAX_PAGES = 4;
const WINDOW_DAYS = 100;
const FIRST_DAY = '2026-11-01';
const DAY_MS = 24 * 3600 * 1000;

const UUID = /^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$/;
